20	import { generateDraftNotes } from '../../api/scheduleApi';
21	import { useFileUpload } from '../../hooks/useFileUpload';
22	import { SCHEDULE_STATUSES } from '../../utils/scheduleHelpers';
23	
24	const emptySchedule = {
25	  townCouncil: '',
26	  liftCompany: '',
27	  blockAddress: '',
28	  scheduledDate: '',
29	  assignedInspector: '',
30	  notes: '',
31	  status: 'Scheduled',
32	  liftId: '',
33	  attachments: [],
34	};
35	
36	// Client-side gate before we ever call the shared upload hook — the presign
37	// endpoint has no file-type/size checks of its own, so this is the only
38	// guard in place today. Limits are generous enough for a phone photo or a
39	// short voice note while keeping uploads fast on a mobile connection.
40	const MAX_ATTACHMENT_SIZE_BYTES = 5 * 1024 * 1024;
41	const ALLOWED_ATTACHMENT_TYPES = [
42	  'image/jpeg',
43	  'image/png',
44	  'image/webp',
45	  'audio/mpeg',
46	  'audio/wav',
47	  'audio/mp4',
48	  'audio/x-m4a',
49	];
50	
51	const schema = Yup.object({
52	  townCouncil: Yup.string().trim().required('Town council is required'),
53	  liftCompany: Yup.string().trim().required('Lift company is required'),
54	  blockAddress: Yup.string().trim().required('Block/Lift address is required'),
55	  scheduledDate: Yup.date().typeError('Enter a valid date').required('Scheduled date is required'),
56	  status: Yup.string().oneOf(SCHEDULE_STATUSES).required(),
57	  assignedInspector: Yup.string(),
58	  notes: Yup.string(),
59	});
60	
61	export default function ScheduleFormDialog({ open, schedule, onClose, onSubmit, initialLiftId }) {
62	  const [draftLoading, setDraftLoading] = useState(false);
63	  const [localError, setLocalError] = useState(null);
64	  const { uploadFile, uploading, progress, error: uploadError } = useFileUpload();
65	
66	  // initialLiftId is only ever consulted for a fresh record (no `schedule`) — e.g. the
67	  // Lift Workflow page's Scheduling step opens this dialog pre-linked to whichever lift
68	  // is currently selected, and locks the picker below so that link can't drift mid-flow.
69	  const formik = useFormik({
70	    enableReinitialize: true,
71	    initialValues: schedule
72	      ? {
73	          ...emptySchedule,
74	          ...schedule,
75	          scheduledDate: schedule.scheduledDate ? schedule.scheduledDate.slice(0, 10) : '',
76	          liftId: schedule.liftId || '',
77	          attachments: schedule.attachments || [],
78	        }
79	      : { ...emptySchedule, liftId: initialLiftId || '' },
80	    validationSchema: schema,
81	    onSubmit: async (values, { setSubmitting }) => {
82	      try {
83	        await onSubmit(values);
84	      } finally {
85	        setSubmitting(false);
86	      }
87	    },
88	  });
89	
90	  // Auto-fills Block/Lift Address from the Lifts module (Student 1's feature)
91	  // when a lift is picked — one click instead of retyping what's already on
92	  // record there. LiftSelect degrades to an empty picker (see LiftSelect.jsx)
93	  // if no lift directory is available yet, so manual entry always still works.
94	  function handleLiftChange(liftId, lift) {
95	    formik.setFieldValue('liftId', liftId);
96	    if (lift) {
97	      formik.setFieldValue('blockAddress', `Lift ${lift.liftCode} — Blk ${lift.block}`);
98	    }
99	  }
100	
101	  async function handleGenerateDraft() {
102	    if (!formik.values.blockAddress) {
103	      setLocalError('Fill in Block/Lift Address before generating a draft.');
104	      return;
105	    }
106	
107	    setDraftLoading(true);
108	    setLocalError(null);
109	    try {
110	      const { notes } = await generateDraftNotes({
111	        townCouncil: formik.values.townCouncil,
112	        liftCompany: formik.values.liftCompany,
113	        blockAddress: formik.values.blockAddress,
114	        assignedInspector: formik.values.assignedInspector,
115	      });
116	      formik.setFieldValue('notes', notes);
117	    } catch (err) {
118	      setLocalError(err.response?.data?.message || 'Failed to generate draft');
119	    } finally {
120	      setDraftLoading(false);
121	    }
122	  }
123	
124	  async function handleFileSelect(e) {
125	    const file = e.target.files[0];
126	    e.target.value = '';
127	    if (!file) return;
128	
129	    if (!ALLOWED_ATTACHMENT_TYPES.includes(file.type)) {
130	      setLocalError('Unsupported file type. Allowed: JPG, PNG, WebP, MP3, WAV, M4A.');
131	      return;
132	    }
133	    if (file.size > MAX_ATTACHMENT_SIZE_BYTES) {
134	      setLocalError('File is too large — 5MB max per attachment.');
135	      return;
136	    }
137	
138	    setLocalError(null);
139	    try {
140	      const url = await uploadFile(file);
141	      formik.setFieldValue('attachments', [
142	        ...formik.values.attachments,
143	        { url, fileName: file.name, fileType: file.type },
144	      ]);
145	    } catch (err) {
146	      setLocalError(err.message);
147	    }
148	  }
149	
150	  function handleRemoveAttachment(index) {
151	    formik.setFieldValue(
152	      'attachments',
153	      formik.values.attachments.filter((_, i) => i !== index)
154	    );
155	  }
156	
157	  return (
158	    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
159	      <form onSubmit={formik.handleSubmit}>
160	        <DialogTitle>{schedule ? 'Edit Schedule' : 'New Spot-Check Schedule'}</DialogTitle>
161	        <DialogContent dividers>
162	          {(localError || uploadError) && (
163	            <Typography color="error" variant="body2" sx={{ mb: 1.5 }}>
164	              {localError || uploadError}
165	            </Typography>
166	          )}
167	
168	          <Box sx={{ mb: 2 }}>
169	            <LiftSelect
170	              value={formik.values.liftId}
171	              onChange={handleLiftChange}
172	              label="Link to a Lift (optional)"
173	              helperText="Auto-fills Block/Lift Address from the Lifts directory"
174	              disabled={Boolean(initialLiftId) && !schedule}
175	            />
176	          </Box>
177	
178	          <Grid container spacing={2}>
179	            <Grid size={6}>
180	              <TextField
181	                name="townCouncil"
182	                label="Town Council"
183	                fullWidth
184	                value={formik.values.townCouncil}
185	                onChange={formik.handleChange}
186	                error={formik.touched.townCouncil && Boolean(formik.errors.townCouncil)}
187	                helperText={formik.touched.townCouncil && formik.errors.townCouncil}
188	              />
189	            </Grid>
190	            <Grid size={6}>
191	              <TextField
192	                name="liftCompany"
193	                label="Lift Company"
194	                fullWidth
195	                value={formik.values.liftCompany}
196	                onChange={formik.handleChange}
197	                error={formik.touched.liftCompany && Boolean(formik.errors.liftCompany)}
198	                helperText={formik.touched.liftCompany && formik.errors.liftCompany}
199	              />
200	            </Grid>
201	            <Grid size={12}>
202	              <TextField
203	                name="blockAddress"
204	                label="Block / Lift Address"
205	                fullWidth
206	                value={formik.values.blockAddress}
207	                onChange={formik.handleChange}
208	                error={formik.touched.blockAddress && Boolean(formik.errors.blockAddress)}
209	                helperText={formik.touched.blockAddress && formik.errors.blockAddress}
210	              />
211	            </Grid>
212	            <Grid size={6}>
213	              <TextField
214	                name="scheduledDate"
215	                label="Scheduled Date"
216	                type="date"
217	                fullWidth
218	                slotProps={{ inputLabel: { shrink: true } }}
219	                value={formik.values.scheduledDate}
220	                onChange={formik.handleChange}
221	                error={formik.touched.scheduledDate && Boolean(formik.errors.scheduledDate)}
222	                helperText={formik.touched.scheduledDate && formik.errors.scheduledDate}
223	              />
224	            </Grid>
225	            <Grid size={6}>
226	              <TextField
227	                select
228	                name="status"
229	                label="Status"
