const mongoose = require('mongoose');

// Matches the client's paper spot-check form fields (Town Council / Lift Company /
// Block-Lift Address) so a schedule entry can stand alone even before the Lifts
// feature's own model/collection exists. Once Lifts is built, `liftId` can be
// populated to link back to the canonical lift record.
const STATUS_VALUES = ['Scheduled', 'Assigned', 'In Progress', 'Completed', 'Cancelled'];

const scheduleSchema = new mongoose.Schema(
  {
    townCouncil: { type: String, required: true, trim: true },
    liftCompany: { type: String, required: true, trim: true },
    blockAddress: { type: String, required: true, trim: true },

    // Optional forward link to the Lifts feature's model.
    liftId: { type: mongoose.Schema.Types.ObjectId, ref: 'Lift', default: null },

    scheduledDate: { type: Date, required: true },
    assignedInspector: { type: String, trim: true, default: '' },

    status: {
      type: String,
      enum: STATUS_VALUES,
      default: 'Scheduled',
    },

    notes: { type: String, trim: true, default: '' },

    // Soft delete, per assignment guide (delete can be optional/soft).
    isDeleted: { type: Boolean, default: false },
  },
  { timestamps: true }
);

scheduleSchema.index({ scheduledDate: 1 });
scheduleSchema.index({ status: 1 });

const Schedule = mongoose.model('Schedule', scheduleSchema);
Schedule.STATUS_VALUES = STATUS_VALUES;

module.exports = Schedule;

const mongoose = require('mongoose');

// Severity matches the terminology already used for embedded defects on inspection
// reports (see models/inspections/Inspection.js) for consistency across the app.
const DEFECT_SEVERITIES = ['Minor', 'Major', 'Critical'];

// A standalone defect has its own lifecycle, separate from the lightweight
// Open/Acknowledged/Verified status used for defects embedded on an inspection report.
const DEFECT_STATUSES = ['Open', 'In Progress', 'Resolved', 'Closed'];

const defectSchema = new mongoose.Schema(
  {
    // Assigned by the controller from the current max in the collection (see
    // nextDefectNo in defectController.js), not an ever-incrementing counter -
    // mirrors reportNo in models/inspections/Inspection.js so deleting the
    // highest-numbered defect and creating a new one reissues that number
    // instead of skipping ahead.
    defectNo: { type: String, required: true, unique: true, trim: true },

    title: { type: String, required: true, trim: true },
    description: { type: String, default: '', trim: true },

    // Optional link to a real lift asset. Not required, since a defect can be
    // logged against a general area (e.g. "Blk 12 lift lobby") before anyone
    // has pinned down exactly which lift is at fault. liftCode/block are a
    // snapshot taken at creation time (see resolveLiftSnapshot in the
    // controller) - a defect is a historical record and shouldn't silently
    // change if the lift's block gets reassigned later.
    liftId: { type: mongoose.Schema.Types.ObjectId, ref: 'Lift', default: null },
    liftCode: { type: String, default: '', trim: true },
    location: { type: String, required: true, trim: true },

    severity: { type: String, enum: DEFECT_SEVERITIES, required: true },
    status: { type: String, enum: DEFECT_STATUSES, default: 'Open' },

    reportedBy: { type: String, default: 'Unknown', trim: true },
    reportedDate: { type: Date, default: Date.now },

    // Set by the controller the moment status first reaches Resolved - kept even if
    // later reopened, so "how long did this take to fix" stays answerable.
    resolvedDate: { type: Date, default: null },
  },
  { timestamps: true }
);

module.exports = mongoose.model('Defect', defectSchema);
module.exports.DEFECT_SEVERITIES = DEFECT_SEVERITIES;
module.exports.DEFECT_STATUSES = DEFECT_STATUSES;

const mongoose = require('mongoose');

const RECTIFICATION_STATUSES = ['Draft', 'Submitted', 'Endorsed'];

const rectificationSchema = new mongoose.Schema(
  {
    // The defect this rectification closes out. Always required - a rectification
    // record only exists in relation to a specific logged defect.
    defectId: { type: mongoose.Schema.Types.ObjectId, ref: 'Defect', required: true },

    rectifiedBy: { type: String, required: true, trim: true },
    liftCompanyName: { type: String, default: '', trim: true },
    dateRectified: { type: Date, required: true },

    // proofPhotos/signatureUrl are NOT enforced with Mongoose `required` even though
    // signatureUrl conceptually "is" required for a finished record - the workflow this
    // feature supports explicitly allows saving a partial record as "Draft" before the
    // lift company has uploaded any photos or signed (see rectificationController.js
    // assertSubmittable). Requiring them at the schema level would make Draft creation
    // impossible. They're validated instead at the controller level, only when the
    // requested/target status is "Submitted".
    proofPhotos: { type: [String], default: [] },
    signatureUrl: { type: String, default: '' },

    remarks: { type: String, default: '', trim: true },

    status: { type: String, enum: RECTIFICATION_STATUSES, default: 'Draft' },

    // Filled in by PATCH /:id/endorse once EM staff sign off after the joint inspection.
    endorsedBy: { type: String, default: '', trim: true },
    endorsedDate: { type: Date, default: null },

    // Soft delete - only allowed while status is "Draft" (see deleteRectification),
    // so a Submitted/Endorsed record can never quietly disappear from the audit trail.
    isDeleted: { type: Boolean, default: false },
  },
  { timestamps: true }
);

module.exports = mongoose.model('Rectification', rectificationSchema);
module.exports.RECTIFICATION_STATUSES = RECTIFICATION_STATUSES;

