17	  app.use(express.json());
18	  app.use('/api/rectifications', rectificationsRoutes);
19	  // Same error-handling middleware as server.js, duplicated here since we don't require
20	  // server.js itself (see header comment).
21	  app.use((err, req, res, next) => {
22	    const statusCode = err.statusCode || 500;
23	    res.status(statusCode).json({ success: false, message: err.message || 'Internal server error' });
24	  });
25	  return app;
26	}
