272	        message={`Delete draft report ${deleteTarget?.reportNo}? This cannot be undone.`}
273	        confirmLabel="Delete"
274	        confirmColor="error"
275	        onConfirm={handleDelete}
276	        onClose={() => setDeleteTarget(null)}
