347	          <Typography variant="body2" color="text.secondary">No defects logged on this report.</Typography>
348	        ) : (
349	          <Stack spacing={2}>
350	            {report.defects.map((d) => (
351	              <Paper key={d._id} variant="outlined" sx={{ p: 2 }}>
