1	import { useEffect, useMemo, useRef, useState } from 'react';
2	import { useSnackbar } from 'notistack';
3	import {
4	  Box,
5	  Button,
6	  Dialog,
7	  DialogActions,
8	  DialogContent,
9	  DialogTitle,
10	  Grid,
11	  IconButton,
12	  MenuItem,
13	  Stack,
14	  TextField,
15	  Tooltip,
16	  Typography,
17	} from '@mui/material';
18	import { DataGrid } from '@mui/x-data-grid';
19	import AddIcon from '@mui/icons-material/Add';
20	import EditIcon from '@mui/icons-material/EditOutlined';
21	import DeleteIcon from '@mui/icons-material/DeleteOutlined';
22	import DownloadIcon from '@mui/icons-material/DownloadOutlined';
23	import UploadIcon from '@mui/icons-material/UploadFileOutlined';
24	import WarningAmberIcon from '@mui/icons-material/WarningAmberOutlined';
25	import ElevatorIcon from '@mui/icons-material/ElevatorOutlined';
26	import BuildIcon from '@mui/icons-material/BuildOutlined';
27	import BlockIcon from '@mui/icons-material/BlockOutlined';
28	import VisibilityIcon from '@mui/icons-material/VisibilityOutlined';
29	import StatCard from '../../components/StatCard';
30	import StatusChip from '../../components/StatusChip';
31	import ConfirmDialog from '../../components/ConfirmDialog';
32	import LiftFormDialog from './LiftFormDialog';
33	import LiftDetailDialog from './LiftDetailDialog';
34	import * as liftApi from '../../api/liftApi';
35	import { LIFT_TYPES, LIFT_STATUSES, isServiceDue } from '../../utils/liftHelpers';
36	import { formatDate } from '../../utils/formatDate';
37	import { exportToCSV } from '../../utils/csvExport';
38	import { parseCSV, rowsToLiftPayloads } from '../../utils/csvImport';
39	import { LIFT_STATUS_COLORS } from '../../theme/statusColors';
40	import { useAuth } from '../../context/AuthContext';
41	
42	const IMPORT_TEMPLATE_COLUMNS = [
43	  { label: 'Lift Code', value: (l) => l.liftCode },
44	  { label: 'Block', value: (l) => l.block },
45	  { label: 'Unit', value: (l) => l.unit },
46	  { label: 'Type', value: (l) => l.type },
47	  { label: 'Capacity', value: (l) => l.capacity },
48	  { label: 'Status', value: (l) => l.status },
49	  { label: 'Manufacturer', value: (l) => l.manufacturer },
50	  { label: 'Install Date', value: (l) => l.installDate },
51	  { label: 'Last Serviced', value: (l) => l.lastServiced },
52	];
53	
54	export default function Lifts() {
55	  const { user } = useAuth();
56	  const { enqueueSnackbar } = useSnackbar();
57	  const canEdit = user.role === 'Admin' || user.role === 'Manager';
58	
59	  const [lifts, setLifts] = useState([]);
60	  const [stats, setStats] = useState(null);
61	  const [loading, setLoading] = useState(true);
62	  const [search, setSearch] = useState('');
63	  const [statusFilter, setStatusFilter] = useState('');
64	  const [typeFilter, setTypeFilter] = useState('');
65	
66	  const [formOpen, setFormOpen] = useState(false);
67	  const [editingLift, setEditingLift] = useState(null);
68	  const [deleteTarget, setDeleteTarget] = useState(null);
69	  const [viewingLift, setViewingLift] = useState(null);
70	
71	  const fileInputRef = useRef(null);
72	  const [importing, setImporting] = useState(false);
73	  const [importResult, setImportResult] = useState(null);
74	
75	  const load = async () => {
76	    setLoading(true);
77	    try {
78	      const [liftList, liftStats] = await Promise.all([liftApi.fetchLifts(), liftApi.fetchLiftStats()]);
79	      setLifts(liftList);
80	      setStats(liftStats);
81	    } catch {
82	      enqueueSnackbar('Failed to load lifts - is the backend running?', { variant: 'error' });
83	    } finally {
84	      setLoading(false);
85	    }
86	  };
87	
88	  useEffect(() => {
89	    load();
90	    // eslint-disable-next-line react-hooks/exhaustive-deps
91	  }, []);
92	
93	  const filteredLifts = useMemo(() => {
94	    return lifts.filter((lift) => {
95	      if (statusFilter && lift.status !== statusFilter) return false;
96	      if (typeFilter && lift.type !== typeFilter) return false;
97	      if (search) {
98	        const haystack = `${lift.liftCode} ${lift.block} ${lift.unit} ${lift.manufacturer}`.toLowerCase();
99	        if (!haystack.includes(search.toLowerCase())) return false;
100	      }
101	      return true;
102	    });
103	  }, [lifts, search, statusFilter, typeFilter]);
104	
105	  const handleSave = async (values) => {
106	    try {
107	      if (editingLift) {
108	        await liftApi.updateLift(editingLift._id, values);
109	        enqueueSnackbar('Lift updated', { variant: 'success' });
110	      } else {
111	        await liftApi.createLift(values);
112	        enqueueSnackbar('Lift created', { variant: 'success' });
113	      }
114	      setFormOpen(false);
115	      setEditingLift(null);
116	      load();
117	    } catch (err) {
118	      enqueueSnackbar(err.response?.data?.message || 'Failed to save lift', { variant: 'error' });
119	    }
120	  };
121	
122	  const handleDelete = async () => {
123	    try {
124	      await liftApi.deleteLift(deleteTarget._id);
125	      enqueueSnackbar('Lift deleted', { variant: 'success' });
126	      setDeleteTarget(null);
127	      load();
128	    } catch (err) {
129	      enqueueSnackbar(err.response?.data?.message || 'Failed to delete lift', { variant: 'error' });
130	    }
131	  };
132	
133	  const handleExport = () => {
134	    exportToCSV('lifts.csv', filteredLifts, [
135	      { label: 'Lift Code', value: (l) => l.liftCode },
136	      { label: 'Block', value: (l) => l.block },
137	      { label: 'Unit', value: (l) => l.unit },
138	      { label: 'Type', value: (l) => l.type },
139	      { label: 'Capacity', value: (l) => l.capacity },
140	      { label: 'Status', value: (l) => l.status },
141	      { label: 'Manufacturer', value: (l) => l.manufacturer },
142	      { label: 'Last Serviced', value: (l) => formatDate(l.lastServiced) },
143	    ]);
144	  };
145	
146	  const handleDownloadTemplate = () => {
147	    exportToCSV(
148	      'lifts-import-template.csv',
149	      [
150	        {
151	          liftCode: 'LIFT-001',
152	          block: 'A',
153	          unit: '01-01',
154	          type: 'Passenger',
155	          capacity: 800,
156	          status: 'Active',
157	          manufacturer: 'Otis',
158	          installDate: '2020-01-15',
159	          lastServiced: '2026-05-01',
160	        },
161	      ],
162	      IMPORT_TEMPLATE_COLUMNS
163	    );
164	  };
165	
166	  const handleImportClick = () => fileInputRef.current?.click();
167	
168	  const handleFileSelected = async (e) => {
169	    const file = e.target.files?.[0];
170	    e.target.value = ''; // reset so re-selecting the same file still fires onChange
171	
172	    if (!file) return;
173	    if (!file.name.toLowerCase().endsWith('.csv')) {
174	      enqueueSnackbar('Only .csv files are supported', { variant: 'error' });
175	      return;
176	    }
177	
178	    setImporting(true);
179	    try {
180	      const text = await file.text();
181	      const payloads = rowsToLiftPayloads(parseCSV(text));
182	      if (!payloads.length) {
183	        enqueueSnackbar('No data rows found in that CSV', { variant: 'warning' });
184	        return;
185	      }
186	
187	      const result = await liftApi.importLifts(payloads);
188	      setImportResult({ ...result, total: payloads.length });
189	      enqueueSnackbar(
190	        result.failed.length
191	          ? `Imported ${result.created} of ${payloads.length} lift(s) — ${result.failed.length} failed`
192	          : `Imported ${result.created} lift(s)`,
193	        { variant: result.failed.length ? 'warning' : 'success' }
194	      );
195	      load();
196	    } catch (err) {
197	      enqueueSnackbar(err.response?.data?.message || 'Failed to import CSV', { variant: 'error' });
198	    } finally {
199	      setImporting(false);
200	    }
201	  };
202	
203	  const columns = [
204	    { field: 'liftCode', headerName: 'Lift Code', width: 130, fontWeight: 600 },
205	    { field: 'block', headerName: 'Block', width: 100 },
206	    { field: 'unit', headerName: 'Unit', width: 90 },
207	    { field: 'type', headerName: 'Type', width: 110 },
208	    { field: 'capacity', headerName: 'Capacity (kg)', width: 130, type: 'number' },
209	    {
210	      field: 'status',
211	      headerName: 'Status',
212	      width: 150,
213	      renderCell: (params) => <StatusChip value={params.value} colorMap={LIFT_STATUS_COLORS} />,
214	    },
215	    {
216	      field: 'lastServiced',
217	      headerName: 'Last Serviced',
218	      width: 160,
219	      renderCell: (params) => (
220	        <Stack direction="row" spacing={0.5} alignItems="center">
221	          <span>{formatDate(params.value)}</span>
222	          {isServiceDue(params.row) && (
223	            <Tooltip title="Service overdue (180+ days)">
224	              <WarningAmberIcon fontSize="small" color="warning" />
225	            </Tooltip>
226	          )}
227	        </Stack>
228	      ),
229	    },
230	    { field: 'manufacturer', headerName: 'Manufacturer', width: 150 },
231	    {
232	      field: 'actions',
233	      headerName: 'Actions',
234	      width: canEdit ? 150 : 70,
235	      sortable: false,
236	      filterable: false,
237	      renderCell: (params) => (
238	        <Stack direction="row">
239	          <IconButton size="small" onClick={() => setViewingLift(params.row)} title="View history">
240	            <VisibilityIcon fontSize="small" />
241	          </IconButton>
242	          {canEdit && (
243	            <>
244	              <IconButton
245	                size="small"
246	                onClick={() => {
247	                  setEditingLift(params.row);
248	                  setFormOpen(true);
249	                }}
250	              >
251	                <EditIcon fontSize="small" />
252	              </IconButton>
253	              <IconButton size="small" onClick={() => setDeleteTarget(params.row)}>
254	                <DeleteIcon fontSize="small" />
255	              </IconButton>
256	            </>
257	          )}
258	        </Stack>
259	      ),
260	    },
261	  ];
262	
263	  return (
264	    <Box>
265	      <Stack direction="row" justifyContent="space-between" alignItems="flex-start" mb={3}>
266	        <Box>
267	          <Typography variant="h4">Lift Management</Typography>
268	          <Typography variant="body2" color="text.secondary">
269	            Track lift assets, service status, and maintenance history.
270	          </Typography>
271	          {canEdit && (
272	            <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 0.5 }}>
273	              Importing lifts?{' '}
274	              <Button
275	                size="small"
276	                onClick={handleDownloadTemplate}
277	                sx={{ p: 0, minWidth: 0, fontSize: 'inherit', verticalAlign: 'baseline' }}
278	              >
279	                Download the CSV template
280	              </Button>
281	            </Typography>
282	          )}
283	        </Box>
284	        <Stack direction="row" spacing={1.5}>
285	          <Button startIcon={<DownloadIcon />} variant="outlined" onClick={handleExport}>
286	            Export CSV
287	          </Button>
288	          {canEdit && (
289	            <>
290	              <input ref={fileInputRef} type="file" accept=".csv,text/csv" hidden onChange={handleFileSelected} />
291	              <Tooltip title="Import lifts from a .csv file">
292	                <span>
293	                  <Button
294	                    startIcon={<UploadIcon />}
295	                    variant="outlined"
296	                    onClick={handleImportClick}
297	                    disabled={importing}
298	                  >
299	                    {importing ? 'Importing…' : 'Import CSV'}
300	                  </Button>
301	                </span>
302	              </Tooltip>
303	              <Button
304	                startIcon={<AddIcon />}
305	                variant="contained"
306	                onClick={() => {
307	                  setEditingLift(null);
308	                  setFormOpen(true);
309	                }}
310	              >
311	                Add Lift
312	              </Button>
313	            </>
314	          )}
315	        </Stack>
316	      </Stack>
317	
318	      {stats && (
319	        <Grid container spacing={2} mb={3}>
320	          <Grid size={{ xs: 12, sm: 6, md: 3 }}>
