    <Box>
      <Stack direction="row" spacing={1.5} alignItems="center" mb={1}>
        <ElevatorOutlinedIcon color="primary" />
        <Typography variant="h4">Lift Workflow</Typography>
      </Stack>
      <Typography variant="body2" color="text.secondary" mb={3}>
