import { useState } from 'react';
import { Box, Button, Chip, Stack, Tooltip, Typography } from '@mui/material';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import ArrowForwardIcon from '@mui/icons-material/ArrowForwardOutlined';
import ChangeCircleOutlinedIcon from '@mui/icons-material/ChangeCircleOutlined';
import WarningAmberIcon from '@mui/icons-material/WarningAmberOutlined';
import StatusChip from '../../components/StatusChip';
import LiftSearchScreen from './LiftSearchScreen';
import WorkflowStepper from './WorkflowStepper';
import SchedulingStep from './steps/SchedulingStep';
import InspectionsStep from './steps/InspectionsStep';
import DefectsStep from './steps/DefectsStep';
import RectificationsStep from './steps/RectificationsStep';
import { WORKFLOW_STEPS } from './workflowSteps';
import { useLiftWorkflowStatus } from './useLiftWorkflowStatus';
import { LIFT_STATUS_COLORS } from '../../theme/statusColors';

const STEP_COMPONENTS = [SchedulingStep, InspectionsStep, DefectsStep, RectificationsStep];

// Orchestrator for the combined Scheduling -> Inspections -> Defects -> Rectifications
// workflow. Each of those four modules keeps its own separate API/controller/model
// (see steps/*.jsx) - this page only picks which lift to work on and which step's scoped
// list+CRUD to show, mirroring the app's existing tab-based (not nested-route) navigation.
export default function LiftWorkflowPage() {
  const [selectedLift, setSelectedLift] = useState(null);
  const [activeStep, setActiveStep] = useState(0);

  // Hooks can't be called conditionally, so this runs even before a lift is picked -
  // useLiftWorkflowStatus no-ops until it's given a real liftId. Keyed on activeStep too
  // so stepping Back/Next re-fetches and picks up anything just created/updated in the
  // step the user came from.
  const { stage, attentionReasons } = useLiftWorkflowStatus(selectedLift?._id, activeStep);

  if (!selectedLift) {
    return (
      <LiftSearchScreen
        onSelectLift={(lift) => {
          setSelectedLift(lift);
          setActiveStep(0);
        }}
      />
    );
  }

  const StepComponent = STEP_COMPONENTS[activeStep];

  // From step 0 (Scheduling) there's no previous step to go back to, so "Back" instead
  // backs out to lift search - same action as "Change Lift" above. Resetting activeStep
  // here too (rather than relying on it already being 0) keeps this correct even if a
  // future step ever gets inserted before Scheduling.
  const handleBack = () => {
    if (activeStep === 0) {
      setSelectedLift(null);
      setActiveStep(0);
    } else {
      setActiveStep((s) => Math.max(0, s - 1));
    }
  };

  return (
    <Box>
      <Stack direction="row" justifyContent="space-between" alignItems="center" mb={2} flexWrap="wrap" gap={1}>
        <Stack direction="row" spacing={1.5} alignItems="center">
          <Typography variant="h5" sx={{ fontWeight: 700 }}>
            {selectedLift.liftCode}
          </Typography>
          <Typography variant="body2" color="text.secondary">
            Blk {selectedLift.block}, {selectedLift.unit}
          </Typography>
          <StatusChip value={selectedLift.status} colorMap={LIFT_STATUS_COLORS} />
          {stage && <Chip label={stage.label} color={stage.color} size="small" variant="outlined" />}
          {attentionReasons.length > 0 && (
            <Tooltip
              title={
                <Box component="ul" sx={{ m: 0, pl: 2 }}>
                  {attentionReasons.map((reason) => (
                    <li key={reason}>{reason}</li>
                  ))}
                </Box>
              }
            >
              <WarningAmberIcon fontSize="small" color="warning" />
            </Tooltip>
          )}
        </Stack>
        <Button
          size="small"
          startIcon={<ChangeCircleOutlinedIcon />}
          onClick={() => setSelectedLift(null)}
        >
          Change Lift
        </Button>
      </Stack>

      <WorkflowStepper activeStep={activeStep} onStepChange={setActiveStep} />

      <Box sx={{ mb: 3 }}>
        <StepComponent lift={selectedLift} />
      </Box>

      <Stack direction="row" justifyContent="space-between">
        <Button startIcon={<ArrowBackIcon />} onClick={handleBack}>
          Back
        </Button>
        <Button
          endIcon={<ArrowForwardIcon />}
          variant="contained"
          disabled={activeStep === WORKFLOW_STEPS.length - 1}
          onClick={() => setActiveStep((s) => Math.min(WORKFLOW_STEPS.length - 1, s + 1))}
        >
          Next
        </Button>
      </Stack>
    </Box>
  );
}

const mongoose = require('mongoose');

// Severity matches the terminology already used for embedded defects on inspection
// reports (see models/inspections/Inspection.js) for consistency across the app.
const DEFECT_SEVERITIES = ['Minor', 'Major', 'Critical'];

// A standalone defect has its own lifecycle, separate from the lightweight
// Open/Acknowledged/Verified status used for defects embedded on an inspection report.
const DEFECT_STATUSES = ['Open', 'In Progress', 'Resolved', 'Closed'];

const defectSchema = new mongoose.Schema(
  {
    // Assigned by the controller from the current max in the collection (see
    // nextDefectNo in defectController.js), not an ever-incrementing counter -
    // mirrors reportNo in models/inspections/Inspection.js so deleting the
    // highest-numbered defect and creating a new one reissues that number
    // instead of skipping ahead.
    defectNo: { type: String, required: true, unique: true, trim: true },

    title: { type: String, required: true, trim: true },
    description: { type: String, default: '', trim: true },

    // Optional link to a real lift asset. Not required, since a defect can be
    // logged against a general area (e.g. "Blk 12 lift lobby") before anyone
    // has pinned down exactly which lift is at fault. liftCode/block are a
    // snapshot taken at creation time (see resolveLiftSnapshot in the
    // controller) - a defect is a historical record and shouldn't silently
    // change if the lift's block gets reassigned later.
    liftId: { type: mongoose.Schema.Types.ObjectId, ref: 'Lift', default: null },
    liftCode: { type: String, default: '', trim: true },
    location: { type: String, required: true, trim: true },

    // Optional link back to the Inspection report that raised this defect (Schedule ->
    // Inspection -> Defect, per the client's workflow doc). Left null for defects logged
    // independently of a report (e.g. a tenant complaint or ad-hoc walkthrough finding) -
    // per the design doc, standalone defects aren't required to trace back to an inspection.
    inspectionId: { type: mongoose.Schema.Types.ObjectId, ref: 'Inspection', default: null },

    severity: { type: String, enum: DEFECT_SEVERITIES, required: true },
    status: { type: String, enum: DEFECT_STATUSES, default: 'Open' },

    reportedBy: { type: String, default: 'Unknown', trim: true },
    reportedDate: { type: Date, default: Date.now },

    // Set by the controller the moment status first reaches Resolved - kept even if
    // later reopened, so "how long did this take to fix" stays answerable.
    resolvedDate: { type: Date, default: null },

    // Soft delete, so deleting the Inspection this defect was raised on can cascade here
    // without destroying the audit trail (see utils/cascadeDelete.js).
    isDeleted: { type: Boolean, default: false },
  },
  { timestamps: true }
);

module.exports = mongoose.model('Defect', defectSchema);
module.exports.DEFECT_SEVERITIES = DEFECT_SEVERITIES;
module.exports.DEFECT_STATUSES = DEFECT_STATUSES;

const mongoose = require('mongoose');

const CHECKLIST_RESULTS = ['Pass', 'Fail', 'N/A'];
const DEFECT_SEVERITIES = ['Minor', 'Major', 'Critical'];
const DEFECT_STATUSES = ['Open', 'Acknowledged', 'Verified'];
const OVERALL_STATUSES = ['Draft', 'Submitted', 'Under Review', 'Closed'];
const COMPLIANCE_VALUES = ['Pass', 'Defect Found'];

const checklistItemSchema = new mongoose.Schema(
  {
    item: { type: String, required: true, trim: true },
    result: { type: String, enum: CHECKLIST_RESULTS, default: 'N/A' },
    remarks: { type: String, default: '', trim: true },
  },
  { _id: false }
);

const defectSchema = new mongoose.Schema({
  description: { type: String, required: true, trim: true },
  severity: { type: String, enum: DEFECT_SEVERITIES, default: 'Minor' },
  photoUrl: { type: String, default: '' },
  status: { type: String, enum: DEFECT_STATUSES, default: 'Open' },
  raisedDate: { type: Date, default: Date.now },
});

const inspectionSchema = new mongoose.Schema(
  {
    // Assigned by the controller (see nextReportNo in inspectionController.js) from the
    // current max in the collection, not an ever-incrementing counter — so deleting the
    // highest-numbered report and creating a new one reissues that same number instead of
    // skipping ahead. unique (not sparse) so two reports can never collide on the same number.
    reportNo: { type: String, required: true, unique: true, trim: true },

    // The lift this report is about, plus the optional scheduled visit it followed up on
    // (Lift -> Schedule -> Inspection, per the client's workflow doc). liftId is the source
    // of truth; liftCode/block below are a snapshot taken at creation time (see controller),
    // not live-joined - an inspection report is a historical record, so it shouldn't silently
    // change if the lift's block gets reassigned months later.
    liftId: { type: mongoose.Schema.Types.ObjectId, ref: 'Lift', required: true },
    scheduleId: { type: mongoose.Schema.Types.ObjectId, ref: 'Schedule', default: null },
    liftCode: { type: String, required: true, trim: true },
    block: { type: String, required: true, trim: true },

    inspectionDate: { type: Date, required: true },
    inspectorName: { type: String, required: true, trim: true },
    contractor: { type: String, default: '', trim: true },
    compliance: { type: String, enum: COMPLIANCE_VALUES, default: 'Pass' },
    checklist: { type: [checklistItemSchema], default: [] },
    defects: { type: [defectSchema], default: [] },
    overallStatus: { type: String, enum: OVERALL_STATUSES, default: 'Draft' },
    contractorNotifiedAt: { type: Date, default: null },
    notes: { type: String, default: '', trim: true },

    // Soft delete, so deleting the Schedule this report followed up on can cascade here
    // without destroying the audit trail (see utils/cascadeDelete.js).
    isDeleted: { type: Boolean, default: false },
  },
  { timestamps: true }
);

module.exports = mongoose.model('Inspection', inspectionSchema);
module.exports.CHECKLIST_RESULTS = CHECKLIST_RESULTS;
module.exports.DEFECT_SEVERITIES = DEFECT_SEVERITIES;
module.exports.DEFECT_STATUSES = DEFECT_STATUSES;
module.exports.OVERALL_STATUSES = OVERALL_STATUSES;
module.exports.COMPLIANCE_VALUES = COMPLIANCE_VALUES;

