13	// straight to Resolved) - status changes go through PUT like any other field, but this
14	// map is checked whenever `status` is present in the request body.
15	const VALID_TRANSITIONS = {
16	  Open: ['In Progress', 'Closed'],
17	  'In Progress': ['Resolved', 'Open'],
18	  Resolved: ['Closed', 'In Progress'],
19	  Closed: ['Open'],
