22	function assertRequiredFields(body) {
23	  const missing = REQUIRED_FIELDS.filter((field) => body[field] === undefined || body[field] === '');
24	  if (missing.length) throw ApiError.badRequest(`Missing required field(s): ${missing.join(', ')}`);
25	}
