27	// Defect numbers are derived from the current max in the collection rather than a
28	// never-decreasing counter, so deleting e.g. DEF-0005 and creating a new defect
29	// reissues DEF-0005 instead of jumping to DEF-0006 (same approach as inspections'
30	// reportNo - see nextReportNo in inspectionController.js).
31	async function nextDefectNo() {
32	  const docs = await Defect.find({}, 'defectNo').lean();
33	  const nums = docs
34	    .map((d) => parseInt(String(d.defectNo).split('-')[1], 10))
35	    .filter((n) => !Number.isNaN(n));
36	  const max = nums.length ? Math.max(...nums) : 0;
37	  return `DEF-${String(max + 1).padStart(4, '0')}`;
38	}
