42	async function resolveLiftSnapshot(liftId) {
43	  if (!liftId) return { liftCode: '' };
44	  const lift = await Lift.findById(liftId).catch(() => null);
45	  if (!lift) throw ApiError.badRequest('Selected lift not found');
46	  return { liftCode: lift.liftCode };
47	}
