1	const Rectification = require('../../models/rectifications/Rectification');
2	const Defect = require('../../models/defects/Defect');
3	const ApiError = require('../../utils/ApiError');
4	const asyncHandler = require('../../utils/asyncHandler');
5	const { ok } = require('../../utils/apiResponse');
6	
7	// Always required, regardless of what status the record is being created as - a
8	// rectification without these three doesn't identify what was fixed, who fixed it,
9	// or when. Contrast with proofPhotos/signatureUrl, which are conditionally required
10	// only once someone tries to reach "Submitted" (see assertSubmittable below).
11	const REQUIRED_FIELDS = ['defectId', 'rectifiedBy', 'dateRectified'];
12	
13	function assertRequiredFields(body) {
14	  const missing = REQUIRED_FIELDS.filter((field) => body[field] === undefined || body[field] === '');
15	  if (missing.length) throw ApiError.badRequest(`Missing required field(s): ${missing.join(', ')}`);
16	}
17	
18	// defectId always has to resolve to a real Defect - same pattern as
19	// defectController.js's resolveLiftSnapshot for an optional liftId, except this link
20	// is mandatory rather than optional.
21	async function assertDefectExists(defectId) {
22	  const defect = await Defect.findOne({ _id: defectId, isDeleted: false }).catch(() => null);
23	  if (!defect) throw ApiError.badRequest('Selected defect not found');
24	}
25	
26	// "Submitted" is the status that means "the lift company says this is done" - it's
27	// meaningless without proof. Enforced here rather than as a Mongoose `required` on the
28	// fields themselves so a "Draft" can still be saved with neither.
29	function assertSubmittable(proofPhotos, signatureUrl) {
30	  const missing = [];
31	  if (!proofPhotos || !proofPhotos.length) missing.push('at least 1 proof photo');
32	  if (!signatureUrl) missing.push('a signature');
33	  if (missing.length) throw ApiError.badRequest(`Cannot submit without ${missing.join(' and ')}`);
34	}
35	
36	function cleanPhotos(proofPhotos) {
37	  return Array.isArray(proofPhotos) ? proofPhotos.filter(Boolean) : [];
38	}
39	
40	// Basic defect info for the Rectifications list/table - description + liftId per the
41	// brief, plus defectNo/title/liftCode since a bare description is often blank and the
42	// table needs *something* readable to identify which defect each row is about.
43	const DEFECT_SUMMARY_FIELDS = 'defectNo title description liftId liftCode';
44	
45	// Rectification has no direct liftId of its own - it only links to a lift via the Defect
46	// it closes out - so scoping this list to a lift means resolving that lift's Defect ids
47	// first and filtering on defectId rather than a field that doesn't exist on this model.
48	const listRectifications = asyncHandler(async (req, res) => {
49	  const { liftId } = req.query;
50	  const filter = { isDeleted: false };
51	
52	  if (liftId) {
53	    const defectIds = await Defect.find({ liftId, isDeleted: false }).distinct('_id');
54	    filter.defectId = { $in: defectIds };
55	  }
56	
57	  const rectifications = await Rectification.find(filter)
58	    .populate('defectId', DEFECT_SUMMARY_FIELDS)
59	    .sort({ createdAt: -1 });
60	  ok(res, rectifications);
61	});
62	
63	const getRectification = asyncHandler(async (req, res) => {
64	  const rectification = await Rectification.findOne({ _id: req.params.id, isDeleted: false }).populate('defectId');
65	  if (!rectification) throw ApiError.notFound('Rectification not found');
66	  ok(res, rectification);
67	});
68	
69	const createRectification = asyncHandler(async (req, res) => {
70	  assertRequiredFields(req.body);
71	  await assertDefectExists(req.body.defectId);
72	
73	  const proofPhotos = cleanPhotos(req.body.proofPhotos);
74	  const signatureUrl = req.body.signatureUrl || '';
75	
76	  // Status is either the explicit choice behind the form's "Save as Draft" / "Submit"
77	  // button, or - if the caller doesn't send one - inferred from whether photos and a
78	  // signature are already attached. Either way "Submitted" only sticks if it's earned.
79	  const requestedStatus = req.body.status || (proofPhotos.length && signatureUrl ? 'Submitted' : 'Draft');
80	  if (!['Draft', 'Submitted'].includes(requestedStatus)) {
81	    throw ApiError.badRequest('New rectifications can only be created as "Draft" or "Submitted"');
82	  }
83	  if (requestedStatus === 'Submitted') {
84	    assertSubmittable(proofPhotos, signatureUrl);
85	  }
86	
87	  const rectification = await Rectification.create({
88	    defectId: req.body.defectId,
89	    rectifiedBy: req.body.rectifiedBy,
90	    liftCompanyName: req.body.liftCompanyName || '',
91	    dateRectified: req.body.dateRectified,
92	    proofPhotos,
93	    signatureUrl,
94	    remarks: req.body.remarks || '',
95	    status: requestedStatus,
96	  });
97	
98	  ok(res, rectification, 'Rectification created', 201);
99	});
100	
101	// Regular field edits. Reaching "Endorsed" is exclusively the job of the dedicated
102	// endorse endpoint below (which also stamps endorsedBy/endorsedDate), so it's not a
103	// valid target of a plain PUT - and once a record IS Endorsed, its proof photos and
104	// signature are locked (the record is finalized) even though remarks and the other
105	// descriptive fields can still be corrected.
106	const updateRectification = asyncHandler(async (req, res) => {
107	  const existing = await Rectification.findOne({ _id: req.params.id, isDeleted: false });
108	  if (!existing) throw ApiError.notFound('Rectification not found');
109	
110	  const { defectId, rectifiedBy, liftCompanyName, dateRectified, proofPhotos, signatureUrl, remarks, status } =
111	    req.body;
112	
113	  const touchesFiles = proofPhotos !== undefined || signatureUrl !== undefined;
114	  if (existing.status === 'Endorsed' && touchesFiles) {
115	    throw ApiError.badRequest('Cannot edit photos or signature on an endorsed rectification');
116	  }
117	
118	  if (defectId !== undefined) {
119	    await assertDefectExists(defectId);
120	    existing.defectId = defectId;
121	  }
122	  if (rectifiedBy !== undefined) {
123	    if (!rectifiedBy.trim()) throw ApiError.badRequest('Rectified By cannot be empty');
124	    existing.rectifiedBy = rectifiedBy;
125	  }
126	  if (liftCompanyName !== undefined) existing.liftCompanyName = liftCompanyName;
127	  if (dateRectified !== undefined) existing.dateRectified = dateRectified;
128	  if (proofPhotos !== undefined) existing.proofPhotos = cleanPhotos(proofPhotos);
129	  if (signatureUrl !== undefined) existing.signatureUrl = signatureUrl;
130	  if (remarks !== undefined) existing.remarks = remarks;
131	
132	  if (status !== undefined && status !== existing.status) {
133	    if (existing.status === 'Endorsed') {
134	      throw ApiError.badRequest('Cannot change the status of an endorsed rectification');
135	    }
136	    if (status === 'Endorsed') {
137	      throw ApiError.badRequest('Use PATCH /:id/endorse to mark a rectification as Endorsed');
138	    }
139	    if (!['Draft', 'Submitted'].includes(status)) {
140	      throw ApiError.badRequest(`Invalid status "${status}"`);
141	    }
142	    if (status === 'Submitted') {
143	      assertSubmittable(existing.proofPhotos, existing.signatureUrl);
144	    }
145	    existing.status = status;
146	  }
147	
148	  await existing.save();
149	  ok(res, existing, 'Rectification updated');
150	});
151	
152	// EM staff's endorsement after the joint on-site inspection. Deliberately its own
